-- Gauge native records. JSON is the versioned domain value; generated columns
-- enforce relational identities while import-kit retains the exact native value.
CREATE TABLE g_assert (ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE g_grants (operator_id TEXT PRIMARY KEY REFERENCES oa_operators(id), person_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('staff','lead','finance')), enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE g_history (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, record_id TEXT NOT NULL, revision TEXT NOT NULL, data TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, at INTEGER NOT NULL);
CREATE TABLE g_receipts (key TEXT PRIMARY KEY, actor TEXT NOT NULL, digest TEXT NOT NULL, result TEXT NOT NULL);
CREATE TABLE g_clients (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE g_people (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE g_engagements (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), client_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.clientId')) STORED NOT NULL REFERENCES g_clients(id), lead_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.leadId')) STORED NOT NULL REFERENCES g_people(id));
CREATE TABLE g_budgets (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), engagement_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.engagementId')) STORED NOT NULL REFERENCES g_engagements(id), status TEXT GENERATED ALWAYS AS (json_extract(data,'$.status')) STORED NOT NULL);
CREATE TABLE g_tasks (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), engagement_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.engagementId')) STORED NOT NULL REFERENCES g_engagements(id));
CREATE TABLE g_milestones (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), engagement_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.engagementId')) STORED NOT NULL REFERENCES g_engagements(id), status TEXT GENERATED ALWAYS AS (json_extract(data,'$.status')) STORED NOT NULL);
CREATE TABLE g_rates (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE g_calendars (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), person_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.personId')) STORED NOT NULL REFERENCES g_people(id));
CREATE TABLE g_leave (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), person_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.personId')) STORED NOT NULL REFERENCES g_people(id));
CREATE TABLE g_staffing (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), engagement_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.engagementId')) STORED NOT NULL REFERENCES g_engagements(id), person_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.personId')) STORED NOT NULL REFERENCES g_people(id));
CREATE TABLE g_time (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), engagement_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.engagementId')) STORED NOT NULL REFERENCES g_engagements(id), person_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.personId')) STORED NOT NULL REFERENCES g_people(id), status TEXT GENERATED ALWAYS AS (json_extract(data,'$.status')) STORED NOT NULL, start_ms INTEGER GENERATED ALWAYS AS (json_extract(data,'$.start')) STORED, end_ms INTEGER GENERATED ALWAYS AS (json_extract(data,'$.end')) STORED, CHECK(end_ms IS NULL OR end_ms>start_ms));
CREATE TABLE g_expenses (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), engagement_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.engagementId')) STORED NOT NULL REFERENCES g_engagements(id), person_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.personId')) STORED NOT NULL REFERENCES g_people(id), status TEXT GENERATED ALWAYS AS (json_extract(data,'$.status')) STORED NOT NULL);
CREATE TABLE g_packets (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), engagement_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.engagementId')) STORED NOT NULL REFERENCES g_engagements(id), status TEXT GENERATED ALWAYS AS (json_extract(data,'$.status')) STORED NOT NULL);
CREATE TABLE g_archives (id TEXT PRIMARY KEY, revision TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE UNIQUE INDEX g_one_timer ON g_time(person_id) WHERE end_ms IS NULL AND start_ms IS NOT NULL;
CREATE TABLE g_files (id TEXT PRIMARY KEY, expense_id TEXT NOT NULL REFERENCES g_expenses(id), name TEXT NOT NULL, media_type TEXT NOT NULL, bytes BLOB NOT NULL, size INTEGER NOT NULL CHECK(size>=0), actor TEXT NOT NULL);
CREATE TABLE g_billing_sources (kind TEXT NOT NULL, source_id TEXT NOT NULL, packet_id TEXT NOT NULL REFERENCES g_packets(id), source_revision TEXT NOT NULL, PRIMARY KEY(kind,source_id));
CREATE TRIGGER g_no_overlap_insert BEFORE INSERT ON g_time WHEN EXISTS(SELECT 1 FROM g_time WHERE person_id=NEW.person_id AND NEW.start_ms<COALESCE(end_ms,9223372036854775807) AND start_ms<COALESCE(NEW.end_ms,9223372036854775807)) BEGIN SELECT RAISE(ABORT,'time_overlap'); END;
CREATE TRIGGER g_no_overlap_update BEFORE UPDATE ON g_time WHEN EXISTS(SELECT 1 FROM g_time WHERE id<>NEW.id AND person_id=NEW.person_id AND NEW.start_ms<COALESCE(end_ms,9223372036854775807) AND start_ms<COALESCE(NEW.end_ms,9223372036854775807)) BEGIN SELECT RAISE(ABORT,'time_overlap'); END;
CREATE TRIGGER g_approved_budget BEFORE UPDATE ON g_budgets WHEN OLD.status='approved' BEGIN SELECT RAISE(ABORT,'immutable_budget'); END;
CREATE TRIGGER g_approved_packet BEFORE UPDATE ON g_packets WHEN OLD.status='approved' BEGIN SELECT RAISE(ABORT,'immutable_packet'); END;
CREATE TRIGGER g_immutable_rate BEFORE UPDATE ON g_rates BEGIN SELECT RAISE(ABORT,'immutable_rate'); END;
CREATE TRIGGER g_billed_time BEFORE UPDATE ON g_time WHEN EXISTS(SELECT 1 FROM g_billing_sources WHERE kind='time' AND source_id=OLD.id) BEGIN SELECT RAISE(ABORT,'billing_dependency'); END;
CREATE TRIGGER g_billed_expense BEFORE UPDATE ON g_expenses WHEN EXISTS(SELECT 1 FROM g_billing_sources WHERE kind='expenses' AND source_id=OLD.id) BEGIN SELECT RAISE(ABORT,'billing_dependency'); END;
CREATE TRIGGER g_billed_milestone BEFORE UPDATE ON g_milestones WHEN EXISTS(SELECT 1 FROM g_billing_sources WHERE kind='milestones' AND source_id=OLD.id) BEGIN SELECT RAISE(ABORT,'billing_dependency'); END;

CREATE TABLE g_exports (packet_id TEXT PRIMARY KEY REFERENCES g_packets(id),actor TEXT NOT NULL,exported_at INTEGER NOT NULL);
CREATE UNIQUE INDEX g_packet_correction ON g_packets(json_extract(data,'$.correctsPacketId')) WHERE status<>'cancelled' AND json_extract(data,'$.correctsPacketId') IS NOT NULL;
